+  const existing = await env.DB.prepare('SELECT * FROM age_review_cases WHERE id = ?')
+    .bind(caseId).first<AgeReviewCase>();
+  if (!existing) return json({ success: false, error: 'Case not found' }, 404, corsHeaders);
